        // banana, then cherry, with a handful of rare, low-frequency filler items.
        Map<String, Integer> trueFrequencies = new LinkedHashMap<>();
        trueFrequencies.put("apple", 50);
        trueFrequencies.put("banana", 30);
        trueFrequencies.put("cherry", 20);
        trueFrequencies.put("date", 5);
        trueFrequencies.put("elderberry", 3);
        trueFrequencies.put("fig", 2);
        trueFrequencies.put("grape", 1);

