// A fixed-size, mergeable structure that estimates item frequencies
// using bounded memory regardless of how many distinct items appear.
class CountMinSketch {
    private final int width;         // number of columns per row
    private final int depth;            // number of independent hash rows
    private final long[][] table;          // the fixed-size counter grid itself
    private final int[] seeds;                // one hash seed per row

    public CountMinSketch(int width, int depth, long seed) {
        this.width = width;                        // store width
        this.depth = depth;                           // store depth
        this.table = new long[depth][width];             // allocate the counter grid, all zeros
        this.seeds = new int[depth];                        // allocate one seed per row
        Random random = new Random(seed);                     // fixed seed, so results are reproducible every run
        for (int i = 0; i < depth; i++) seeds[i] = random.nextInt(); // one independent seed per row
    }

    // Increments one cell per row for this item, in constant time
    // regardless of how many distinct items the sketch has ever seen.
    public void add(String item) {
        for (int row = 0; row < depth; row++) {
            int column = hash(item, row); // which cell this row maps this item to
            table[row][column]++;            // bump that cell
        }
    }

    // Returns the minimum value across every cell this item hashed to,
    // the tightest safe upper bound on its true count, since a collision
    // can only ever inflate a cell, never deflate one.
    public long estimate(String item) {
        long minimum = Long.MAX_VALUE;              // smallest cell value seen so far
        for (int row = 0; row < depth; row++) {
            int column = hash(item, row);              // which cell this row maps this item to
            minimum = Math.min(minimum, table[row][column]); // keep the smallest across every row
        }
        return minimum; // the tightest safe estimate
    }

    // Merges another sketch of identical dimensions into this one by
    // summing corresponding cells, which is exactly what lets independent
    // ingestion workers each maintain their own partial sketch.
    public void mergeFrom(CountMinSketch other) {
        for (int row = 0; row < depth; row++) {
            for (int column = 0; column < width; column++) {
                table[row][column] += other.table[row][column]; // add the other sketch's cell into this one
            }
        }
    }

    private int hash(String item, int row) {
        int hashCode = (item.hashCode() ^ seeds[row]); // combine the item's hash with this row's own seed
        return Math.floorMod(hashCode, width);            // map into a valid column index
    }
}

// Tracks the current best candidates for a top K list, backed by a
// Count-Min Sketch's estimates rather than exact per-item counters.
class TopKTracker {
    private final CountMinSketch sketch;                      // the shared frequency estimator
    private final int k;                                          // how many top items to track
    private final PriorityQueue<ItemEstimate> minHeap;               // the current best candidates, smallest on top
    private final Set<String> trackedItems = new HashSet<>();          // which items are currently in the heap

    public TopKTracker(CountMinSketch sketch, int k) {
        this.sketch = sketch; // store the shared sketch
        this.k = k;              // store how many top items to keep
        this.minHeap = new PriorityQueue<>(Comparator.comparingLong(e -> e.estimatedCount)); // ordered smallest-first
    }

    // Called whenever an item occurs, re-evaluating whether it now
    // belongs among the current top K candidates.
    public void onItemOccurred(String item) {
        sketch.add(item);                              // record this occurrence in the shared sketch
        long currentEstimate = sketch.estimate(item);      // this item's updated estimate
        if (trackedItems.contains(item)) {
            refreshHeap(); // this item's position in the heap may have changed
            return;
        }
        if (minHeap.size() < k) {                                          // still room in the top K
            minHeap.add(new ItemEstimate(item, currentEstimate));              // add it directly
            trackedItems.add(item);
        } else if (currentEstimate > minHeap.peek().estimatedCount) {          // beats the current weakest entry
            ItemEstimate evicted = minHeap.poll();                                // remove the weakest
            trackedItems.remove(evicted.item);
            minHeap.add(new ItemEstimate(item, currentEstimate));                    // add the new, stronger item
            trackedItems.add(item);
        }
    }

    private void refreshHeap() {
        List<ItemEstimate> refreshed = new ArrayList<>();                         // rebuilt entries with fresh estimates
        for (ItemEstimate entry : minHeap) {
            refreshed.add(new ItemEstimate(entry.item, sketch.estimate(entry.item))); // re-read this item's current estimate
        }
        minHeap.clear();           // drop the stale heap
        minHeap.addAll(refreshed); // rebuild it with fresh values
    }

    public List<ItemEstimate> currentTopK() {
        return new ArrayList<>(minHeap); // a snapshot of the current top K candidates
    }

    static class ItemEstimate {
        String item;               // the item itself
        long estimatedCount;          // its current estimated frequency

        ItemEstimate(String item, long estimatedCount) {
            this.item = item;                     // store the item
            this.estimatedCount = estimatedCount;    // store its estimate
        }
    }
}

