// A fixed-size, mergeable structure that estimates item frequencies
// using bounded memory regardless of how many distinct items appear.
class CountMinSketch {
public:
    CountMinSketch(int width, int depth, long seed)
        : width_(width), depth_(depth), table_(depth, std::vector<long>(width, 0)) {
        std::mt19937 rng(static_cast<unsigned>(seed));   // fixed seed, so results are reproducible every run
        std::uniform_int_distribution<int> dist(0, INT_MAX);
        for (int i = 0; i < depth; i++) seeds_.push_back(dist(rng));   // one hash seed per row
    }

    // Increments one cell per row for this item, in constant time
    // regardless of how many distinct items the sketch has ever seen.
    void add(const std::string& item) {
        for (int row = 0; row < depth_; row++) {
            int column = hash(item, row);   // which cell this row maps this item to
            table_[row][column]++;             // bump that cell
        }
    }

    // Returns the minimum value across every cell this item hashed to,
    // the tightest safe upper bound on its true count, since a collision
    // can only ever inflate a cell, never deflate one.
    long estimate(const std::string& item) const {
        long minimum = LONG_MAX;                 // smallest cell value seen so far
        for (int row = 0; row < depth_; row++) {
            int column = hash(item, row);           // which cell this row maps this item to
            minimum = std::min(minimum, table_[row][column]);   // keep the smallest across every row
        }
        return minimum;   // the tightest safe estimate
    }

private:
    int hash(const std::string& item, int row) const {
        size_t h = std::hash<std::string>{}(item) ^ static_cast<size_t>(seeds_[row]);   // combine the item's hash with this row's own seed
        int column = static_cast<int>(h % static_cast<size_t>(width_));
        return column;   // map into a valid column index
    }

    int width_;   // number of columns per row
    int depth_;      // number of independent hash rows
    std::vector<std::vector<long>> table_;   // the fixed-size counter grid itself
    std::vector<int> seeds_;                    // one hash seed per row
};

struct ItemEstimate {
    std::string item;         // the item itself
    long estimatedCount;         // its current estimated frequency
};

// Tracks the current best candidates for a top K list, backed by a
// Count-Min Sketch's estimates rather than exact per-item counters.
class TopKTracker {
public:
    TopKTracker(CountMinSketch* sketch, int k) : sketch_(sketch), k_(k) {}

    // Called whenever an item occurs, re-evaluating whether it now
    // belongs among the current top K candidates.
    void onItemOccurred(const std::string& item) {
        sketch_->add(item);                              // record this occurrence in the shared sketch
        long currentEstimate = sketch_->estimate(item);      // this item's updated estimate
        if (trackedItems_.count(item)) {
            refreshHeap();   // this item's position in the heap may have changed
            return;
        }
        if (static_cast<int>(heap_.size()) < k_) {                                       // still room in the top K
            heap_.push_back({ item, currentEstimate });
            trackedItems_.insert(item);
        } else {
            auto weakest = std::min_element(heap_.begin(), heap_.end(),
                                             [](auto& a, auto& b) { return a.estimatedCount < b.estimatedCount; });
            if (currentEstimate > weakest->estimatedCount) {   // beats the current weakest entry
                trackedItems_.erase(weakest->item);
                *weakest = { item, currentEstimate };
                trackedItems_.insert(item);
            }
        }
    }

    void refreshHeap() {
        for (auto& e : heap_) e.estimatedCount = sketch_->estimate(e.item);   // re-read every item's current estimate
    }

    std::vector<ItemEstimate> currentTopK() const { return heap_; }   // a snapshot of the current top K candidates

private:
    CountMinSketch* sketch_;   // the shared frequency estimator
    int k_;                       // how many top items to track
    std::vector<ItemEstimate> heap_;
    std::set<std::string> trackedItems_;   // which items are currently in the heap
};

int main() {
    std::cout << std::boolalpha;
    CountMinSketch sketch(200, 5, 42L);   // small demo sketch, fixed seed for reproducibility
    TopKTracker tracker(&sketch, 3);           // track the top 3 items

    // A stream with clearly different true frequencies: apple most common, then
    // banana, then cherry, with a handful of rare, low-frequency filler items.
    std::vector<std::pair<std::string, int>> trueFrequencies = {
        { "apple", 50 }, { "banana", 30 }, { "cherry", 20 }, { "date", 5 }, { "elderberry", 3 }, { "fig", 2 }, { "grape", 1 },
    };

    for (auto& [word, count] : trueFrequencies) {
        for (int i = 0; i < count; i++) {
            tracker.onItemOccurred(word);   // feed this item's occurrences into the tracker
        }
    }

    std::cout << "Current top 3 estimated items:\n";
    auto topK = tracker.currentTopK();
    std::sort(topK.begin(), topK.end(), [](auto& a, auto& b) { return a.estimatedCount > b.estimatedCount; });   // print highest first
    for (auto& item : topK) std::cout << "  " << item.item << " -> estimated " << item.estimatedCount << "\n";

    std::cout << "True frequencies for comparison:\n";
    std::map<std::string, int> freqMap(trueFrequencies.begin(), trueFrequencies.end());
    for (auto& word : { "apple", "banana", "cherry", "date" }) {
        long estimate = sketch.estimate(word);
        int trueCount = freqMap[word];
        std::cout << "  " << word << ": true=" << trueCount << " estimate=" << estimate
                  << " (estimate never undercounts: " << (estimate >= trueCount) << ")\n";
    }

    std::set<std::string> topKNames;
    for (auto& item : topK) topKNames.insert(item.item);
    bool containsAll = topKNames.count("apple") && topKNames.count("banana") && topKNames.count("cherry");
    std::cout << "Top 3 correctly contains apple, banana, and cherry: " << containsAll << "\n";
    return 0;
}

