        System.out.println("True frequencies for comparison:");
        for (String item : Arrays.asList("apple", "banana", "cherry", "date")) {
            long estimate = sketch.estimate(item);
            int trueCount = trueFrequencies.get(item);
            System.out.println("  " + item + ": true=" + trueCount + " estimate=" + estimate + " (estimate never undercounts: " + (estimate >= trueCount) + ")");
        }

        Set<String> topKNames = new HashSet<>();
        for (TopKTracker.ItemEstimate item : topK) topKNames.add(item.item);
        System.out.println("Top 3 correctly contains apple, banana, and cherry: " + (topKNames.contains("apple") && topKNames.contains("banana") && topKNames.contains("cherry")));
    }
